CREATE TABLE public.traces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), query text NOT NULL, claim text NOT NULL, entities jsonb NOT NULL DEFAULT '[]', window_days integer NOT NULL DEFAULT 30, stage text NOT NULL DEFAULT 'queued', status text NOT NULL DEFAULT 'Whisper', confidence integer NOT NULL DEFAULT 0, smoke_score integer NOT NULL DEFAULT 0, summary_md text NOT NULL DEFAULT '', confirm_signals jsonb NOT NULL DEFAULT '[]', kill_signals jsonb NOT NULL DEFAULT '[]', watch_signals jsonb NOT NULL DEFAULT '[]', origin_mention_id uuid, watching boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), checked_at timestamptz NOT NULL DEFAULT now(), error text, lease_until timestamptz, lease_token uuid, paused boolean NOT NULL DEFAULT false, rechecking boolean NOT NULL DEFAULT false, research_result jsonb);
GRANT SELECT ON public.traces TO anon, authenticated; GRANT UPDATE (watching) ON public.traces TO anon, authenticated; GRANT ALL ON public.traces TO service_role;
ALTER TABLE public.traces ENABLE ROW LEVEL SECURITY;
CREATE POLICY traces_public_read ON public.traces FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY traces_public_watch ON public.traces FOR UPDATE TO anon,authenticated USING(true) WITH CHECK(true);
CREATE TABLE public.mentions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trace_id uuid NOT NULL REFERENCES public.traces(id) ON DELETE CASCADE, url text NOT NULL, title text NOT NULL, domain text NOT NULL, outlet text NOT NULL, published_at timestamptz, snippet text NOT NULL DEFAULT '', attribution_quotes jsonb NOT NULL DEFAULT '[]', stance text NOT NULL DEFAULT 'unrelated', sourcing text NOT NULL DEFAULT 'unsourced', attributes_to text, is_origin boolean NOT NULL DEFAULT false, is_independent boolean NOT NULL DEFAULT false, paywalled boolean NOT NULL DEFAULT false, source_api text NOT NULL DEFAULT 'you_search', involved_party boolean NOT NULL DEFAULT false, mainstream boolean NOT NULL DEFAULT false, classified boolean NOT NULL DEFAULT false, contents_read boolean NOT NULL DEFAULT false, UNIQUE(trace_id,url));
GRANT SELECT ON public.mentions TO anon,authenticated; GRANT ALL ON public.mentions TO service_role;
ALTER TABLE public.mentions ENABLE ROW LEVEL SECURITY; CREATE POLICY mentions_public_read ON public.mentions FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.status_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trace_id uuid NOT NULL REFERENCES public.traces(id) ON DELETE CASCADE, status text NOT NULL, reason text NOT NULL, at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.status_history TO anon,authenticated; GRANT ALL ON public.status_history TO service_role;
ALTER TABLE public.status_history ENABLE ROW LEVEL SECURITY; CREATE POLICY history_public_read ON public.status_history FOR SELECT TO anon,authenticated USING(true);
CREATE INDEX mentions_trace_date ON public.mentions(trace_id,published_at);
CREATE INDEX traces_checked ON public.traces(checked_at DESC);
CREATE FUNCTION public.acquire_trace_lease(p_id uuid,p_token uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.traces SET lease_until=now()+interval '120 seconds',lease_token=p_token WHERE id=p_id AND NOT paused AND stage NOT IN ('done','error') AND (lease_until IS NULL OR lease_until<now()); RETURN FOUND; END; $$;
REVOKE ALL ON FUNCTION public.acquire_trace_lease(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.acquire_trace_lease(uuid,uuid) TO service_role;